<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { ArrowUpRight, Check, ChevronDown, ChevronRight, CircleDollarSign, Copy, Download, Folder, GitBranch, MessageSquare, Search, Settings2, X } from 'lucide-vue-next'
import { ANALYSIS_MODELS, ANALYSIS_PRICE_KEYS, ANALYSIS_PRICES, ANALYSIS_SESSIONS, analysisActivity, analysisBudgetValid, analysisExport, analysisFamilies, analysisPriceValid, analysisProjects, analysisRange, analysisSummary, analysisTotal, type AnalysisPrice, type AnalysisPrices, type AnalysisRange, type AnalysisRole, type AnalysisSession } from './analysis-story'

// Native evidence: LocalUsageView.swift:188,258,327,987; ProviderDetailView.swift:550,635.
const root = ref<HTMLElement>(), dialog = ref<HTMLDialogElement>(), searchInput = ref<HTMLInputElement>()
const range = ref<AnalysisRange>(7), role = ref<AnalysisRole>('all'), query = ref('')
const prices = ref<AnalysisPrices>(JSON.parse(JSON.stringify(ANALYSIS_PRICES)))
const estimateEnabled = ref(true), monthlyBudget = ref(5)
const rows = computed(() => analysisRange(range.value))
const summary = computed(() => analysisSummary(rows.value, prices.value))
const families = computed(() => analysisFamilies(rows.value, query.value, role.value))
const projects = computed(() => analysisProjects(rows.value))
const month = computed(() => analysisSummary(ANALYSIS_SESSIONS.filter(row => row.date >= '2026-11-01'), prices.value))
const expanded = ref(new Set(['demo-main-interface']))
const detail = ref(''), activeProject = ref('Atlas'), status = ref('')
const activityScope = ref<'main' | 'subagent'>('main')
const activity = computed(() => analysisActivity(rows.value, activityScope.value))
const budgetText = ref('5'), draftEstimate = ref(true)
function makeDraftPrices(saved: AnalysisPrices): Record<string, Record<keyof AnalysisPrice, string>> {
  return Object.fromEntries(ANALYSIS_MODELS.map(model => [model, Object.fromEntries(ANALYSIS_PRICE_KEYS.map(({ key }) => [key, String(saved[model]?.[key] ?? 0)]))])) as Record<string, Record<keyof AnalysisPrice, string>>
}
const draftPrices = ref(makeDraftPrices(ANALYSIS_PRICES))
const draftEnabled = ref<Record<string, boolean>>({})
const visible = ref(false), pageHidden = ref(false)
let cleanup = () => {}, announcedTimer: ReturnType<typeof setTimeout> | undefined
const currency = (value: number | null) => value === null ? '未设置参考价' : `$${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 4 })}`
const count = (value: number) => value >= 1_000_000 ? `${(value / 1_000_000).toFixed(1)}M` : value >= 1000 ? `${(value / 1000).toFixed(1)}K` : String(value)
const period = computed(() => range.value === 1 ? '今日' : range.value === 365 ? '全年' : `${range.value} 天`)
const currentProject = computed(() => projects.value.find(project => project.name === activeProject.value) ?? projects.value[0])
const draftValid = computed(() => !draftEstimate.value || (analysisBudgetValid(budgetText.value) && ANALYSIS_MODELS.every(model => !draftEnabled.value[model] || analysisPriceValid(draftPrice(model)))))
const budgetRatio = computed(() => monthlyBudget.value > 0 ? Math.min(1, Math.max(0, (month.value.estimate ?? 0) / monthlyBudget.value)) : 0)
const ranges: { days: AnalysisRange; title: string }[] = [{ days: 1, title: '今日' }, { days: 7, title: '7 天' }, { days: 30, title: '30 天' }, { days: 365, title: '全年' }]
const roles: { id: AnalysisRole; title: string }[] = [{ id: 'all', title: '全部' }, { id: 'main', title: '主会话' }, { id: 'subagent', title: '子 Agent' }]

function setRange(value: AnalysisRange) { range.value = value; query.value = ''; detail.value = ''; activeProject.value = analysisProjects(analysisRange(value))[0]?.name ?? '' }
function toggleFamily(id: string) { const next = new Set(expanded.value); next.has(id) ? next.delete(id) : next.add(id); expanded.value = next }
function announce(message: string) { status.value = message; clearTimeout(announcedTimer); announcedTimer = setTimeout(() => { status.value = '' }, 6000) }
function openChat(row: AnalysisSession) {
  // No invented UUID, deep link or external navigation: these are isolated public examples.
  announce(`“${row.title}”是示例会话。Mac 版可打开有有效线程链接的 Codex 聊天。`)
}
function exportData(format: 'csv' | 'json') {
  const blob = new Blob([analysisExport(rows.value, prices.value, format)], { type: format === 'csv' ? 'text/csv;charset=utf-8' : 'application/json' })
  const url = URL.createObjectURL(blob), link = document.createElement('a')
  link.href = url; link.download = `Donvis-demo-${range.value}d.${format}`; link.click()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
  announce(`已导出 ${period.value}固定示例 ${format.toUpperCase()}，包含示例项目名，不含对话或账号。`)
}
function draftPrice(model: string): AnalysisPrice {
  const item = draftPrices.value[model]
  return { input: Number(item?.input ?? 0), cacheRead: Number(item?.cacheRead ?? 0), cacheWrite: Number(item?.cacheWrite ?? 0), output: Number(item?.output ?? 0) }
}
async function openPricing() {
  draftEstimate.value = estimateEnabled.value; budgetText.value = monthlyBudget.value > 0 ? String(monthlyBudget.value) : ''
  draftEnabled.value = Object.fromEntries(ANALYSIS_MODELS.map(model => [model, !!prices.value[model]]))
  draftPrices.value = makeDraftPrices(prices.value)
  await nextTick(); dialog.value?.showModal()
}
function savePricing() {
  if (!draftValid.value) return
  estimateEnabled.value = draftEstimate.value
  if (draftEstimate.value) {
    prices.value = Object.fromEntries(ANALYSIS_MODELS.filter(model => draftEnabled.value[model]).map(model => [model, draftPrice(model)]))
    monthlyBudget.value = Number(budgetText.value) || 0
  }
  dialog.value?.close(); announce('示例参考价已保存，估值已按当前单价更新。')
}
onMounted(() => {
  const observer = new IntersectionObserver(entries => { visible.value = entries.some(entry => entry.isIntersecting) }, { threshold: .06 })
  if (root.value) observer.observe(root.value)
  const hidden = () => { pageHidden.value = document.hidden }
  hidden(); document.addEventListener('visibilitychange', hidden)
  cleanup = () => { observer.disconnect(); document.removeEventListener('visibilitychange', hidden) }
})
onBeforeUnmount(() => { cleanup(); clearTimeout(announcedTimer); dialog.value?.close() })
</script>

<template>
  <section id="analysis" ref="root" class="analysis-story" :class="{ 'analysis-visible': visible, 'analysis-paused': !visible || pageHidden }" aria-labelledby="analysis-title">
    <div class="analysis-inner">
      <header class="analysis-heading"><span class="analysis-eyebrow">费用与会话</span><h2 id="analysis-title">从总账，<em>追到每次协作。</em></h2><p>从参考费用到项目、会话与子 Agent，层层看清。</p></header>
      <div class="analysis-native">
        <div class="analysis-toolbar"><div class="analysis-toolbar-title"><Copy :size="15"/><strong>费用与会话</strong><small>此 Mac · 固定示例</small></div><div class="analysis-actions"><button type="button" @click="openPricing"><Settings2 :size="13"/>设置参考价</button><button type="button" @click="exportData('csv')"><Download :size="13"/>CSV</button><button type="button" @click="exportData('json')"><Download :size="13"/>JSON</button></div></div>
        <div class="analysis-range" role="group" aria-label="费用与会话统计范围"><button v-for="item in ranges" :key="item.days" type="button" :aria-pressed="range === item.days" @click="setRange(item.days)">{{ item.title }}</button></div>
        <div class="analysis-proof-grid">
          <article class="analysis-panel analysis-cost">
            <div class="analysis-card-label"><CircleDollarSign :size="15"/><h3>API 参考费用</h3><label class="analysis-estimate-toggle"><input v-model="estimateEnabled" type="checkbox"/><span>显示估值</span></label></div>
            <div class="analysis-amount" aria-live="polite"><span>{{ estimateEnabled ? currency(summary.estimate) : '—' }}</span><small>{{ period }} · USD</small></div>
            <p class="analysis-cost-note">{{ !estimateEnabled ? '默认仅展示本机 Token 与会话统计' : summary.unpriced ? `${summary.unpriced} 条记录缺少参考价` : '按已保存单价估算，不代表实际账单' }}</p>
            <div v-if="estimateEnabled && monthlyBudget > 0" class="analysis-budget"><div><span>本月参考估值 / 预算</span><strong>{{ currency(month.estimate) }} <i>/ {{ currency(monthlyBudget) }}</i></strong></div><div class="analysis-budget-track" role="meter" aria-label="本月参考估值占预算比例" :aria-valuenow="Math.round(budgetRatio * 100)" aria-valuemin="0" aria-valuemax="100"><span :style="{ transform: `scaleX(${budgetRatio})` }"></span></div></div>
            <div v-else class="analysis-budget-empty">{{ estimateEnabled ? '本月参考预算未设置' : '参考估值由你主动开启' }}</div>
            <button type="button" class="analysis-text-button" @click="openPricing">模型单价与本月参考预算 <ArrowUpRight :size="13"/></button>
          </article>
          <article class="analysis-panel analysis-projects">
            <div class="analysis-card-label"><Folder :size="15"/><h3>会话项目分布</h3><small>按主会话数</small></div>
            <div class="analysis-project-body">
              <div class="analysis-donut"><svg viewBox="0 0 160 160" role="img" :aria-label="`${summary.main} 个主会话，关联 ${summary.projects} 个项目`"><circle cx="80" cy="80" r="61" fill="none" stroke="#e8eaf0" stroke-width="19"/><circle v-for="project in projects" :key="project.name" cx="80" cy="80" r="61" fill="none" :stroke="project.color" :stroke-width="currentProject?.name === project.name ? 23 : 17" pathLength="1" :stroke-dasharray="`${Math.max(0, project.fraction - .012)} 1`" :stroke-dashoffset="-project.start" transform="rotate(-90 80 80)"/></svg><div><strong>{{ summary.main }}</strong><span>主会话</span></div></div>
              <div class="analysis-project-list"><button v-for="project in projects" :key="project.name" type="button" :aria-pressed="currentProject?.name === project.name" :style="{ '--project-color': project.color }" @click="activeProject = project.name"><i></i><span>{{ project.name }}</span><strong>{{ project.count }}</strong><small>{{ Math.round(project.fraction * 100) }}%</small></button><div class="analysis-project-titles"><span v-for="title in currentProject?.titles.slice(0, 2)" :key="title">{{ title }}</span><small v-if="(currentProject?.titles.length ?? 0) > 2">等 {{ currentProject?.count }} 个主会话</small></div></div>
            </div>
          </article>
        </div>
        <div class="analysis-metrics"><div><MessageSquare :size="14"/><span>会话</span><strong>{{ summary.main }}<small>个</small></strong></div><div><GitBranch :size="14"/><span>子 Agent 会话</span><strong>{{ summary.subagents }}<small>个</small></strong></div><div><Copy :size="14"/><span>使用模型</span><strong>{{ summary.models }}<small>种</small></strong></div><div><Folder :size="14"/><span>关联项目</span><strong>{{ summary.projects }}<small>个</small></strong></div></div>
        <article class="analysis-panel analysis-sessions">
          <div class="analysis-sessions-heading"><div><GitBranch :size="15"/><h3>主会话与子 Agent 归属</h3></div><label class="analysis-search"><Search :size="13"/><input ref="searchInput" v-model="query" type="search" placeholder="搜索会话" aria-label="搜索示例会话标题"/></label></div>
          <div class="analysis-activity"><div class="analysis-activity-scope" role="group" aria-label="会话活动统计角色"><button type="button" :aria-pressed="activityScope === 'main'" @click="activityScope = 'main'">主会话活动</button><button type="button" :aria-pressed="activityScope === 'subagent'" @click="activityScope = 'subagent'">子 Agent 活动</button></div><div><strong>{{ activityScope === 'main' ? activity.messages : activity.responses }}</strong><span>{{ activityScope === 'main' ? '用户消息' : '模型响应' }}</span></div><div><strong>{{ activity.tools }}</strong><span>工具调用</span></div><div><strong>{{ activity.skillReads }}</strong><span>技能读取请求</span></div></div>
          <div class="analysis-session-subline"><div class="analysis-role-switch" role="group" aria-label="查看会话角色"><button v-for="item in roles" :key="item.id" type="button" :aria-pressed="role === item.id" @click="role = item.id">{{ item.title }}</button></div><span>含子总计只汇总一次</span></div>
          <div class="analysis-family-list" tabindex="0" aria-label="会话家族，可滚动查看">
            <div v-for="family in families" :key="family.id" class="analysis-family" :class="{ 'analysis-family-open': expanded.has(family.id) }">
              <button type="button" class="analysis-family-toggle" :aria-expanded="expanded.has(family.id)" :aria-controls="`analysis-family-${family.id}`" @click="toggleFamily(family.id)"><ChevronDown v-if="expanded.has(family.id)" :size="13"/><ChevronRight v-else :size="13"/><div><strong>{{ family.title }}</strong><small>{{ family.main?.project ?? '未记录项目' }}<span v-if="family.children.length"> · {{ family.children.length }} 个子 Agent</span></small></div><span>{{ count(family.total) }} <small>Token</small></span></button>
              <div v-if="expanded.has(family.id)" :id="`analysis-family-${family.id}`" class="analysis-family-details"><div class="analysis-family-totals"><div><span>主会话自身</span><strong>{{ count(family.direct) }}</strong></div><div><span>子 Agent 合计</span><strong>{{ count(family.childTotal) }}</strong></div><div><span>含子总计</span><strong>{{ count(family.total) }}</strong></div></div><p v-if="!family.main" class="analysis-empty">该主会话本期没有直接用量或活动记录</p>
                <div v-for="row in family.rows" :key="row.id" class="analysis-session-row"><div class="analysis-session-top"><button type="button" class="analysis-session-label" :aria-expanded="detail === row.id" :aria-controls="`analysis-detail-${row.id}`" @click="detail = detail === row.id ? '' : row.id"><GitBranch v-if="row.role === 'subagent'" :size="12"/><MessageSquare v-else :size="12"/><span>{{ row.title }}<small>{{ row.model }} · {{ row.effort }}</small></span><strong>{{ count(analysisTotal(row.tokens)) }}</strong><ChevronDown :size="12"/></button></div><div v-if="detail === row.id" :id="`analysis-detail-${row.id}`" class="analysis-token-details"><div v-for="tile in [{ title: '未缓存输入', value: row.tokens.input }, { title: '缓存读取', value: row.tokens.cacheRead }, { title: '输出', value: row.tokens.output }, { title: '推理', value: row.tokens.reasoning }]" :key="tile.title"><small>{{ tile.title }}</small><strong>{{ count(tile.value) }}</strong></div><div class="analysis-chat-row"><span>推理已包含在输出内</span><button type="button" @click="openChat(row)">打开聊天 <ArrowUpRight :size="12"/></button></div></div></div>
              </div>
            </div><p v-if="!families.length" class="analysis-empty">没有匹配的会话</p>
          </div>
        </article>
        <div class="analysis-footnote"><span>仅统计可读取的本机记录 · 参考单价为示例</span><span>导出包含项目名，不含对话正文、账号或密钥</span></div>
      </div>
      <p class="analysis-status" role="status" aria-live="polite"><Check v-if="status" :size="13"/>{{ status }}</p>
    </div>
    <dialog ref="dialog" class="analysis-pricing-dialog" aria-labelledby="analysis-pricing-title">
      <form @submit.prevent="savePricing"><header><h3 id="analysis-pricing-title">API 参考估值</h3><button type="button" aria-label="关闭参考价设置" @click="dialog?.close()"><X :size="17"/></button></header><label class="analysis-editor-toggle"><input v-model="draftEstimate" type="checkbox"/>显示 API 参考估值（非账单）</label><template v-if="draftEstimate"><div class="analysis-price-unit"><span>USD / 百万 Token · 示例单价</span><label>本月参考预算 USD<input v-model="budgetText" type="number" min="0" max="999999999" step="any" placeholder="可留空"/></label></div><div class="analysis-price-table"><div v-for="model in ANALYSIS_MODELS" :key="model" class="analysis-price-model"><label><input v-model="draftEnabled[model]" type="checkbox"/>{{ model }}</label><label v-for="item in ANALYSIS_PRICE_KEYS" :key="item.key"><span>{{ item.title }}</span><input v-model="draftPrices[model][item.key]" :disabled="!draftEnabled[model]" type="number" min="0" max="1000000" step="any" :aria-label="`${model} ${item.title} USD每百万Token`"/></label></div></div></template><p v-else class="analysis-editor-off">默认仅展示本机 Token 与会话统计。</p><p class="analysis-pricing-error" role="status">{{ draftValid ? '未配置价格的模型会标为未计价，不当作免费。' : '请输入有效的非负参考价和大于 0 的参考预算。' }}</p><footer><button type="button" @click="dialog?.close()">取消</button><button type="submit" :disabled="!draftValid">保存</button></footer></form>
    </dialog>
  </section>
</template>

<style scoped>
