.analysis-inner { max-width:1140px; margin:auto; }.analysis-heading { margin-bottom:25px; }.analysis-eyebrow { display:block; color:#626775; font-size:10px; letter-spacing:.12em; margin-bottom:12px; }.analysis-heading h2 { margin:0; font-size:clamp(36px,4.2vw,57px); line-height:1.13; font-weight:550; letter-spacing:-.065em; }.analysis-heading h2 em { font-style:normal; color:#8050d3; }.analysis-heading p { margin:12px 0 0; font-size:13px; color:#686b74; }
.analysis-native { position:relative; font-family:-apple-system,BlinkMacSystemFont,'PingFang SC',sans-serif; font-size:12px; border:1px solid #d9dce3; border-radius:18px; padding:20px; background:#f9fafb; box-shadow:0 25px 70px #1c25520c,0 1px 0 #fff inset; }.analysis-native button,.analysis-pricing-dialog button { cursor:pointer; }.analysis-native button:focus-visible,.analysis-native input:focus-visible,.analysis-pricing-dialog :is(button,input):focus-visible,.analysis-family-list:focus-visible { outline:2px solid #8050d3; outline-offset:3px; }.analysis-native button { font:inherit; }.analysis-toolbar { display:flex; justify-content:space-between; align-items:center; gap:20px; }.analysis-toolbar-title { display:flex; align-items:center; gap:8px; }.analysis-toolbar-title strong { font-size:15px; font-weight:600; }.analysis-toolbar-title small { font-size:10px; color:#818590; margin-left:7px; }.analysis-actions { display:flex; gap:6px; }.analysis-actions button { display:flex; align-items:center; justify-content:center; gap:5px; min-height:32px; border:1px solid #dfe1e7; border-radius:7px; padding:0 10px; background:#fff; font-size:11px; }.analysis-actions button:hover { background:#f0f1f6; }.analysis-range { display:flex; width:max-content; max-width:100%; background:#e9ebf0; border-radius:7px; padding:3px; margin:15px 0; }.analysis-range button { min-width:55px; min-height:29px; padding:4px 13px; border:0; border-radius:5px; background:none; color:#737784; font-size:11px; }.analysis-range button[aria-pressed=true] { background:#fff; color:#24262c; box-shadow:0 1px 3px #18213c18; }
